export async function loadEmbeddedMigrations(): Promise<ReadonlyArray<Migration>> {
  return Promise.all(
    EMBEDDED_MIGRATIONS.map((migration) =>
      migrationFromText(migration.version, migration.fileName, migration.sql, migration.trustedChecksum)
    )
  );
}
